{
  "name": "AreaDetector GatherN 数据汇聚插件",
  "name_en": "AreaDetector GatherN Data Gather Plugin",
  "manufacturer": "",
  "description": "这是一个用于面阵探测器数据采集链路的图像/数组汇聚插件组件，通常接在上游 areaDetector 插件之后，从源插件接收 NDArray 数据并进行成组汇集，供后续显示、处理或保存使用。它常见于同步辐射、显微成像和其他基于二维探测器的实验数据流程中。",
  "description_en": "This is an image/array gathering plugin component used in an area detector acquisition pipeline. It typically sits downstream of another areaDetector plugin, receives NDArray data from a source plugin, and groups or gathers the data for later display, processing, or file output. It is commonly used in synchrotron, microscopy, and other 2D detector-based experimental workflows.",
  "actions": [
    {
      "action_name": "auto-stage",
      "description": "准备该汇聚插件进入采集或联机工作状态。",
      "description_en": "Prepare the gather plugin for acquisition or online operation."
    },
    {
      "action_name": "auto-enable_on_stage",
      "description": "设定在进入 stage 时启用该插件。",
      "description_en": "Configure the plugin to be enabled when staged."
    },
    {
      "action_name": "auto-disable_on_stage",
      "description": "设定在进入 stage 时禁用该插件。",
      "description_en": "Configure the plugin to be disabled when staged."
    },
    {
      "action_name": "auto-ensure_blocking",
      "description": "将插件设为阻塞处理模式。",
      "description_en": "Set the plugin to blocking processing mode."
    },
    {
      "action_name": "auto-ensure_nonblocking",
      "description": "将插件设为非阻塞处理模式。",
      "description_en": "Set the plugin to non-blocking processing mode."
    },
    {
      "action_name": "auto-array_pixels",
      "description": "获取当前图像数组的像素总数。",
      "description_en": "Get the total pixel count of the current image array."
    },
    {
      "action_name": "auto-read_configuration",
      "description": "获取该插件的当前配置参数。",
      "description_en": "Get the current configuration of the plugin."
    },
    {
      "action_name": "auto-source_plugin",
      "description": "获取当前上游源插件信息。",
      "description_en": "Get the current upstream source plugin information."
    },
    {
      "action_name": "auto-describe_configuration",
      "description": "获取该插件配置项的说明信息。",
      "description_en": "Get descriptive metadata for the plugin configuration."
    },
    {
      "action_name": "auto-image",
      "description": "获取当前输出图像或数组数据。",
      "description_en": "Get the current output image or array data."
    },
    {
      "action_name": "auto-set",
      "description": "设置该插件的状态或参数值。",
      "description_en": "Set the plugin state or parameter value."
    },
    {
      "action_name": "auto-warmup",
      "description": "对插件执行预热初始化，使其为后续采集做好准备。",
      "description_en": "Perform plugin warm-up initialization so it is ready for subsequent acquisition."
    }
  ],
  "tag_hints": [
    "area detector",
    "NDArray pipeline",
    "image aggregation",
    "detector data processing",
    "multi-frame gather",
    "EPICS areaDetector",
    "scientific imaging"
  ]
}

